<section class="panel spaced inbound-mail-panel"><div class="panel-head premium-card-head"><span class="premium-card-head-icon"><i class="fa-solid fa-inbox"></i></span><div><b>Recepción de correo · canal omnicanal</b><small>SMTP envía correo. IMAP o Microsoft Graph reciben correo y permiten convertirlo en conversaciones de ZYNKO.</small></div></div><form method="post" id="inboundMailConfigForm"><input type="hidden" name="action" value="email_inbound_save"><input type="hidden" name="method" value="<?=htmlspecialchars($method)?>"><input type="hidden" name="sender" value="<?=htmlspecialchars($cfg['correo']??'')?>"><input type="hidden" name="graph_user" value="<?=htmlspecialchars($cfg['graph_user']??'')?>"><div class="settings-grid"><div class="field"><label>Método de recepción</label><select class="select2" name="inbound_method" id="inboundMethod"><option value="NONE" <?=($cfg['inbound_method']??'NONE')==='NONE'?'selected':''?>>Sin recepción entrante</option><option value="IMAP" <?=($cfg['inbound_method']??'')==='IMAP'?'selected':''?>>IMAP · buzón estándar</option><option value="GRAPH" <?=($cfg['inbound_method']??'')==='GRAPH'?'selected':''?>>Microsoft Graph · buzón Microsoft 365</option></select></div><div class="field"><label>Estado</label><label class="switch-line"><input type="checkbox" name="inbound_enabled" <?=!empty($cfg['inbound_enabled'])?'checked':''?>><span></span> Recepción activa</label></div></div><div class="settings-grid imap-inbound-fields"><div class="field"><label>Servidor IMAP</label><input name="imap_host" value="<?=htmlspecialchars($cfg['imap_host']??'')?>" placeholder="outlook.office365.com / imap.gmail.com"></div><div class="field"><label>Puerto IMAP</label><input name="imap_port" inputmode="numeric" value="<?=htmlspecialchars((string)($cfg['imap_port']??993))?>"></div><div class="field"><label>Seguridad</label><select class="select2" name="imap_secure"><option value="ssl" <?=($cfg['imap_secure']??'ssl')==='ssl'?'selected':''?>>SSL/TLS</option><option value="tls" <?=($cfg['imap_secure']??'')==='tls'?'selected':''?>>STARTTLS</option><option value="none" <?=($cfg['imap_secure']??'')==='none'?'selected':''?>>Sin cifrado · no recomendado</option></select></div><div class="field"><label>Usuario IMAP</label><input name="imap_username" value="<?=htmlspecialchars($cfg['imap_username']??'')?>" placeholder="correo@dominio.com"></div><div class="field"><label>Contraseña / App Password</label><input name="imap_password" type="password" autocomplete="new-password" placeholder="<?=empty($cfg['imap_password'])?'Obligatoria':'•••••••• (conservar si queda vacío)'?>"></div><div class="field"><label>Carpeta</label><input name="imap_folder" value="<?=htmlspecialchars($cfg['imap_folder']??'INBOX')?>" placeholder="INBOX"></div></div><div class="graph-inbound-help notice info"><i class="fa-brands fa-microsoft"></i><div><b>Recepción Microsoft Graph</b><span>Usa el mismo Tenant ID, Client ID, Client Secret y buzón configurados arriba. La aplicación de Azure debe tener permiso de aplicación <strong>Mail.Read</strong> con consentimiento de administrador.</span></div></div><div class="mail-inbound-status"><span class="status <?=($cfg['inbound_last_test_status']??'')==='ok'?'ok':(($cfg['inbound_last_test_status']??'')==='error'?'warning':'')?>"><?=htmlspecialchars(($cfg['inbound_last_test_status']??'')==='ok'?'Validado':(($cfg['inbound_last_test_status']??'')==='error'?'Requiere atención':'Sin probar'))?></span><small><?=htmlspecialchars($cfg['inbound_last_test_message']??'Guarda la configuración y luego prueba la recepción.')?></small></div><div class="actions-inline"><button class="primary" type="submit"><i class="fa-solid fa-floppy-disk"></i> Guardar recepción</button><button class="soft" type="button" id="testInboundMail"><i class="fa-solid fa-plug-circle-check"></i> Probar recepción</button></div></form></section>
<form method="post"><input type="hidden" name="action" value="notification_settings_save"><section class="panel spaced"><div class="panel-head premium-card-head"><span class="premium-card-head-icon" aria-hidden="true"><i class="fa-solid fa-envelope-circle-check"></i></span><div><b>Notificaciones automáticas</b><small>Elige qué eventos generan correo. Los mensajes se agrupan para evitar saturar la bandeja.</small></div></div><div class="settings-grid notification-settings-grid"><div class="field"><label>Seguridad</label><label class="switch-line"><input name="login_enabled" type="checkbox" <?=!empty($notif['login_enabled'])?'checked':''?>><span></span> Inicios de sesión</label></div><div class="field"><label>Conversaciones</label><label class="switch-line"><input name="message_enabled" type="checkbox" <?=!empty($notif['message_enabled'])?'checked':''?>><span></span> Nuevos mensajes</label></div><div class="field"><label>NIVO</label><label class="switch-line"><input name="handoff_enabled" type="checkbox" <?=!empty($notif['handoff_enabled'])?'checked':''?>><span></span> Solicitudes de agente</label></div><div class="field"><label>Sistema</label><label class="switch-line"><input name="critical_enabled" type="checkbox" <?=!empty($notif['critical_enabled'])?'checked':''?>><span></span> Eventos críticos</label></div><div class="field full notification-cooldown"><label>Agrupar mensajes durante</label><select class="select2" name="cooldown_minutes"><option value="0" <?=$notif['cooldown_minutes']==0?'selected':''?>>Sin agrupación</option><option value="5" <?=$notif['cooldown_minutes']==5?'selected':''?>>5 minutos</option><option value="10" <?=$notif['cooldown_minutes']==10?'selected':''?>>10 minutos · recomendado</option><option value="15" <?=$notif['cooldown_minutes']==15?'selected':''?>>15 minutos</option><option value="30" <?=$notif['cooldown_minutes']==30?'selected':''?>>30 minutos</option><option value="60" <?=$notif['cooldown_minutes']==60?'selected':''?>>1 hora</option></select><small class="hint">Si una conversación recibe varios mensajes en este período, ZYNKO envía solo la primera alerta.</small></div></div><div class="notification-actions"><button class="primary" type="submit"><i class="fa-solid fa-bell"></i> Guardar notificaciones</button><span class="hint"><i class="fa-solid fa-circle-info"></i> Usa el proveedor activo configurado arriba.</span></div></section></form>
<section class="panel spaced"><div class="panel-head premium-card-head"><span class="premium-card-head-icon" aria-hidden="true"><i class="fa-solid fa-envelope-circle-check"></i></span><div><b>Estado</b><small><?=empty($cfg)?'Correo no configurado: no se enviarán emails hasta guardar un proveedor.':'Proveedor guardado: '.htmlspecialchars($method).'.'?></small></div></div></section>
<script>document.addEventListener('DOMContentLoaded',()=>{const routes=document.getElementById('mailSenderRoutes');if(routes){const request=async(fd)=>{const r=await fetch(location.href,{method:'POST',headers:{'X-ZYNKO-AJAX':'1'},body:fd});const j=await r.json();showNotify(j.ok?'success':'error',j.ok?'Correo':'Error',j.message);return j;};const initial=()=>JSON.stringify([...routes.querySelectorAll('input[type=email]')].map(e=>e.value));let saved=initial();routes.addEventListener('submit',async e=>{e.preventDefault();const b=routes.querySelector('button[type=submit]');b.disabled=true;try{const j=await request(new FormData(routes));if(j.ok){const before=JSON.parse(saved);[...routes.querySelectorAll('input[type=email]')].forEach((el,i)=>{if(before[i]!==el.value){const status=el.closest('.mail-route-card').querySelector('.mail-route-status');status.classList.remove('ok');status.textContent=el.value?'Pendiente de prueba':'Usa buzón principal';}});saved=initial();}}catch(err){showNotify('error','Correo',err.message);}finally{b.disabled=false;}});routes.querySelectorAll('.mail-route-test').forEach(b=>b.addEventListener('click',async()=>{if(saved!==initial()){showNotify('info','Correo','Guarde los remitentes antes de realizar la prueba.');return;}const fd=new FormData();fd.append('action','email_test');fd.append('csrf',routes.elements.csrf.value);fd.append('purpose',b.dataset.purpose);b.disabled=true;try{const j=await request(fd);const card=b.closest('.mail-route-card');if(j.ok&&card.querySelector('input').value){const status=card.querySelector('.mail-route-status');status.classList.add('ok');status.textContent='Prueba aceptada';}}catch(err){showNotify('error','Correo',err.message);}finally{b.disabled=false;}}));}document.getElementById('testConfiguredMail')?.addEventListener('click',async()=>{const b=document.getElementById('testConfiguredMail'),old=b.innerHTML;b.disabled=true;b.innerHTML='<i class="fa-solid fa-spinner fa-spin"></i> Enviando prueba…';try{const fd=new FormData();fd.append('action','email_test');const r=await fetch(location.href,{method:'POST',headers:{'X-ZYNKO-AJAX':'1'},body:fd});const j=await r.json();showNotify(j.ok?'success':'error',j.ok?'Correo verificado':'No se pudo enviar',j.message)}catch(e){showNotify('error','No se pudo enviar',e.message)}finally{b.disabled=false;b.innerHTML=old}});const m=document.getElementById('mailMethod'),ss=[...document.querySelectorAll('.smtp-fields')],gs=[...document.querySelectorAll('.graph-fields')];const sync=()=>{const graph=m.value==='GRAPH';ss.forEach(s=>{s.hidden=graph;s.querySelectorAll('input,select').forEach(e=>e.disabled=graph)});gs.forEach(g=>{g.hidden=!graph;g.querySelectorAll('input,select').forEach(e=>e.disabled=!graph)});};m.addEventListener('change',sync);if(window.jQuery)jQuery(m).on('change.mailProvider',sync);sync();const inbound=document.getElementById('inboundMethod'),imap=[...document.querySelectorAll('.imap-inbound-fields')],graphHelp=document.querySelector('.graph-inbound-help');const syncInbound=()=>{const v=inbound?.value||'NONE';imap.forEach(x=>x.hidden=v!=='IMAP');if(graphHelp)graphHelp.hidden=v!=='GRAPH'};inbound?.addEventListener('change',syncInbound);syncInbound();document.getElementById('testInboundMail')?.addEventListener('click',async()=>{const b=document.getElementById('testInboundMail'),old=b.innerHTML;b.disabled=true;b.innerHTML='<i class="fa-solid fa-spinner fa-spin"></i> Probando…';try{const fd=new FormData();fd.append('action','email_inbound_test');const r=await fetch(location.href,{method:'POST',headers:{'X-ZYNKO-AJAX':'1'},body:fd});const j=await r.json();showNotify(j.ok?'success':'error',j.ok?'Recepción validada':'Recepción no disponible',j.message);if(j.ok)setTimeout(()=>location.reload(),500)}catch(e){showNotify('error','No se pudo probar',e.message)}finally{b.disabled=false;b.innerHTML=old}});});</script>
